from pathlib import Path

ВИНЯТОК = __import__('re').compile(r'^[ \t]+([^\s:]+):')


def розібрати(шлях):
    записи = []
    поточний = None
    with шлях.open(encoding='utf-8') as файл:
        for рядок in файл:
            рядок = рядок.rstrip('\r\n')
            if not рядок.strip():
                continue
            if рядок[0] in ' \t':
                # Рядок продовження поточного запису
                if поточний is not None:
                    поточний['рядки'].append(рядок)
            else:
                # Початок нового запису: перші два слова — дата і час
                час = ' '.join(рядок.split()[:2])
                поточний = {'час': час, 'рядки': []}
                записи.append(поточний)
    return записи


def main():
    шлях = Path('дані') / 'журнал.txt'
    статистика = {}  # тип -> [кількість, перший час, останній час]

    for запис in розібрати(шлях):
        тип = None
        for рядок in запис['рядки']:
            м = ВИНЯТОК.match(рядок)
            if м:
                тип = м.group(1)  # останній такий рядок визначає тип
        if тип is None:
            continue

        час = запис['час']
        if тип in статистика:
            п = статистика[тип]
            п[0] += 1
            п[1] = min(п[1], час)
            п[2] = max(п[2], час)
        else:
            статистика[тип] = [1, час, час]

    відсортовано = sorted(статистика.items(), key=lambda kv: (-kv[1][0], kv[0]))
    for тип, (n, перший, останній) in відсортовано:
        print(f'{тип}: {n} ({перший}, {останній})')


if __name__ == '__main__':
    main()

